<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {segments} from './marginChecker'
import {reading} from './marginOverview'
import type {MarginOverviewData} from './marginOverview'
const props=defineProps<{data:MarginOverviewData;loading?:boolean}>()
const market=ref('TWSE'),period=ref('60'),hover=ref<number|null>(null),scroll=ref<HTMLDivElement|null>(null),viewport=ref(900),expanded=ref(true)
let observer:ResizeObserver|undefined
const chosen=computed(()=>props.data.markets.find(m=>m.market===market.value)),points=computed(()=>{const p=chosen.value?.series||[];return period.value==='all'?p:p.slice(-Number(period.value))})
const activeIndex=computed(()=>hover.value??Math.max(0,points.value.length-1)),activeDate=computed(()=>points.value[activeIndex.value]?.date||props.data.as_of),active=computed(()=>points.value[activeIndex.value])
const width=computed(()=>Math.max(720,viewport.value,points.value.length*12+110)),left=78,right=25,top=30,bottom=242
const x=(i:number)=>left+i/Math.max(1,points.value.length-1)*(width.value-left-right)
const range=computed(()=>{const a=points.value.map(p=>p.official_loan).filter((v):v is number=>v!=null);if(!a.length)return [0,1];const lo=Math.min(...a)/1e8,hi=Math.max(...a)/1e8,pad=Math.max((hi-lo)*.12,hi*.01,1);return [Math.max(0,lo-pad),hi+pad]})
const y=(v:number)=>bottom-(v-range.value[0]!)/(range.value[1]!-range.value[0]!)*(bottom-top)
const paths=computed(()=>segments(points.value.map(p=>p.official_loan==null?null:p.official_loan/1e8),x,y))
const ticks=computed(()=>[...new Set([0,Math.floor((points.value.length-1)/2),points.value.length-1])].filter(i=>i>=0))
const fmt=(v:number|null|undefined,d=2)=>v==null?'—':v.toLocaleString('zh-TW',{maximumFractionDigits:d})
const money=(v:number|null|undefined)=>v==null?'—':Math.abs(v)>=1e8?fmt(v/1e8)+' 億':Math.abs(v)>=1e4?fmt(v/1e4)+' 萬':fmt(v)+' 元'
const signedMoney=(v:number|null|undefined)=>v==null?'未驗證':(v>0?'+':v<0?'−':'')+money(Math.abs(v))
const pct=(v:number|null|undefined)=>v==null?'—':(v>0?'+':'')+fmt(v*100)+'%'
function remember(){try{localStorage.setItem('margin-overview.preferences.v1',JSON.stringify({market:market.value,period:period.value,expanded:expanded.value}))}catch{}}
async function reset(){hover.value=null;await nextTick();observer?.disconnect();if(scroll.value){observer?.observe(scroll.value);viewport.value=scroll.value.clientWidth;scroll.value.scrollLeft=scroll.value.scrollWidth}}
function choose(m:string){market.value=m;remember();reset()}
function toggle(e:Event){expanded.value=(e.target as HTMLDetailsElement).open;remember();if(expanded.value)reset()}
function move(e:PointerEvent){const b=(e.currentTarget as SVGElement).getBoundingClientRect();hover.value=Math.max(0,Math.min(points.value.length-1,Math.round(((e.clientX-b.left)/b.width*width.value-left)/(width.value-left-right)*Math.max(1,points.value.length-1))))}
function key(e:KeyboardEvent){if(!['ArrowLeft','ArrowRight','Escape'].includes(e.key))return;e.preventDefault();if(e.key==='Escape'){hover.value=null;return}hover.value=Math.max(0,Math.min(points.value.length-1,activeIndex.value+(e.key==='ArrowLeft'?-1:1)));if(scroll.value)scroll.value.scrollLeft=Math.max(0,x(hover.value)-scroll.value.clientWidth/2)}
watch([period,()=>props.data.as_of],()=>{remember();reset()})
onMounted(()=>{try{const p=JSON.parse(localStorage.getItem('margin-overview.preferences.v1')||'{}');if(['TWSE','TPEX'].includes(p.market))market.value=p.market;if(['60','120','all'].includes(p.period))period.value=p.period;if(typeof p.expanded==='boolean')expanded.value=p.expanded}catch{};observer=new ResizeObserver(e=>{const w=e[0]?.contentRect.width;if(w&&Math.abs(viewport.value-w)>1)viewport.value=w});reset()})
onUnmounted(()=>observer?.disconnect())
</script>
<template>
 <section class="loan-overview" aria-label="官方融資觀測總覽" :aria-busy="loading">
  <header><div><div class="eyebrow">OFFICIAL FINANCING · OBSERVATIONS</div><h2>兩市融資 · 先看資金變化</h2><p>官方總額與來源涵蓋可先觀察；維持率與風險訊號待本金模型通過。</p></div><span class="date" data-overview-date>{{hover==null?'查閱日':'游標觀察'}} {{activeDate}}</span></header>
  <div class="totals"><article v-for="m in data.markets" :key="m.market" :data-market-total="m.market"><div class="card-heading"><h3>{{m.label}}官方融資金額</h3><span>{{reading(m,activeDate).point?.official_loan==null?'本日缺來源':'官方已保存'}}</span></div><strong>{{money(reading(m,activeDate).point?.official_loan)}}</strong><div class="changes"><div><small>較前一交易日</small><b>{{signedMoney(reading(m,activeDate).change1.amount)}}</b><span>{{pct(reading(m,activeDate).change1.pct)}}</span></div><div><small>較20交易日前</small><b>{{signedMoney(reading(m,activeDate).change20.amount)}}</b><span>{{pct(reading(m,activeDate).change20.pct)}}</span></div></div><p v-if="reading(m,activeDate).point?.official_loan==null">不沿用舊值，不填0。{{m.last_observation&&m.last_observation.date<=activeDate?'最近已存來源 '+m.last_observation.date:'本日尚無可用金額'}}</p><p v-else>含該市場ETF等融資標的；金額增減不直接判定多空。</p><footer><span>至查閱日來源 {{m.available_days}} / {{m.expected_days}} 日</span><a :href="m.source_url" target="_blank" rel="noopener">{{m.label==='上市'?'證交所':'櫃買中心'}} ↗</a></footer></article></div>
  <details class="trend" :open="expanded" @toggle="toggle" aria-label="官方融資趨勢區塊"><summary><span>官方融資金額走勢</span><small>缺漏不連線 · 收折狀態會保留</small></summary><div class="trend-body"><div class="controls"><div class="segmented" role="group" aria-label="官方融資趨勢市場"><button :aria-pressed="market==='TWSE'" @click="choose('TWSE')">上市</button><button :aria-pressed="market==='TPEX'" @click="choose('TPEX')">上櫃</button></div><label>顯示期間<select v-model="period" aria-label="官方融資趨勢期間"><option value="60">近60個交易日</option><option value="120">近120個交易日</option><option value="all">全部已保存日曆</option></select></label><span class="coverage">{{points[0]?.date}} ～ {{points.at(-1)?.date}}</span></div><p class="hint">可正常左右捲動；游標同步上方兩市日期與金額，移開回查閱日。也可用方向鍵移動，Esc回到查閱日。</p>
   <div ref="scroll" class="chart-scroll" tabindex="0" aria-label="官方融資金額走勢，可左右捲動" @keydown="key"><svg :width="width" height="300" :viewBox="`0 0 ${width} 300`" role="img" :aria-label="`${chosen?.label}官方融資金額走勢`" @pointermove="move" @pointerleave="hover=null"><rect :width="width" height="300" fill="white"/><text x="12" y="17" class="axis-title">官方金額 · 億元</text><g v-if="paths.length"><g v-for="v in [range[0]!,((range[0]!+range[1]!)/2),range[1]!]" :key="v"><line :x1="left" :x2="width-right" :y1="y(v)" :y2="y(v)" class="grid"/><text :x="left-10" :y="y(v)+4" text-anchor="end" class="tick">{{fmt(v,1)}}</text></g><path v-for="(p,i) in paths" :key="i" :d="p" :class="['loan-line',market==='TPEX'?'otc':'']"/></g><text v-else :x="width/2" y="135" text-anchor="middle" class="missing">這段期間尚無已保存金額，未補值或連線</text><g v-if="points.length"><line :x1="x(activeIndex)" :x2="x(activeIndex)" :y1="top" :y2="bottom" class="cursor"/><circle v-if="active?.official_loan!=null" :cx="x(activeIndex)" :cy="y(active.official_loan/1e8)" r="5" class="active-dot"/><text v-for="i in ticks" :key="i" :x="x(i)" y="280" :text-anchor="i===0?'start':i===points.length-1?'end':'middle'" class="tick">{{points[i]?.date}}</text></g></svg></div>
   <p class="source-meta">{{chosen?.label}} · {{activeDate}} · {{active?.official_loan==null?'該日缺官方融資來源':'該來源實際取得 '+active.retrieved_at?.slice(0,16).replace('T',' ')}}。{{data.vintage}}。</p></div></details>
  <div class="status-grid"><article><small>維持率與風險分布</small><b>尚未驗證</b><p>本金、暖機與方法敏感度未通過；不把缺值當作低風險。</p></article><article><small>清洗與背離</small><b>尚不可確認</b><p>事件研究保留逐段觀察；不將官方總額大減直接視為買點。</p></article><article><small>目前方法驗收</small><b>{{data.validation?.as_of||'尚待保存'}}</b><p>這是最新方法檢查日期，與上方歷史查看日分開，不冒充當時已發布的判斷。</p></article></div>
 </section>
</template>
