:inherit;color:inherit;background:#fff;border:1px solid #dce5d6;padding:8px 12px;border-radius:7px;font-size:12px;max-width:100%}button{cursor:pointer}.segmented{display:flex;background:#eef3e9;padding:4px;border-radius:8px;gap:4px}.segmented button{border:0;background:transparent}.segmented button[aria-pressed=true]{background:#fff;box-shadow:0 2px 5px #3b5a3d16;font-weight:700}.coverage{font-size:11px;color:#90a083;padding-bottom:8px}.chart-scroll{overflow-x:auto;max-width:100%;overscroll-behavior-x:contain}.chart-scroll svg{display:block;touch-action:pan-x pan-y}.axis-title,.tick{fill:#8b9b80;font-size:11px}.grid{stroke:#e5ebdf;stroke-dasharray:4 5}.loan-line{fill:none;stroke:#5d8a73;stroke-width:2.6}.loan-line.otc{stroke:#6c8ca5}.cursor{stroke:#8e9d82;stroke-dasharray:4 5}.active-dot{fill:#496d59;stroke:#fff;stroke-width:2}.missing{fill:#a28a50;font-size:13px}.source-meta{font-size:10px;margin:12px 0 0}.status-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:20px 0}.status-grid article{background:#f8f6ef;border:1px solid #eee7d7;border-radius:10px;padding:18px}.status-grid small{display:block;font-size:11px;color:#a18b5b}.status-grid b{display:block;font-size:18px;margin:9px 0;color:#927b43}.status-grid p{font-size:11px;line-height:1.9;color:#8c947f;margin:0}@media(max-width:700px){header{flex-direction:column}h2{font-size:22px}.totals{grid-template-columns:1fr}.totals article{padding:20px}.totals strong{font-size:32px}.status-grid{grid-template-columns:1fr}.trend>summary{padding:18px;flex-wrap:wrap;gap:10px}.trend-body{padding:0 16px 16px}.trend>summary small{width:100%;padding-left:19px}.controls{gap:12px}.coverage{width:100%;padding:0}.changes b{font-size:17px}}
